import os
import hmac
import hashlib
import json
import secrets
from typing import Optional, Dict, List, Any
from dataclasses import dataclass, field
from enum import IntEnum


class Permission(IntEnum):
    READ = 0
    WRITE = 1
    EXECUTE = 2
    ADMIN = 3


@dataclass
class AccessToken:
    user_id: str
    permissions: List[int]
    issued_at: float
    nonce: str = field(default_factory=lambda: secrets.token_hex(16))


class PermissionRegistry:
    """Manages permission levels and access control."""

    def __init__(self):
        self._registry: Dict[str, AccessToken] = {}
        self._secret = os.environ.get('AUTH_SECRET', '').encode()
        if not self._secret:
            raise RuntimeError("AUTH_SECRET environment variable required")
        # Permission level names for audit logging
        self._level_names = ['read', 'write', 'execute', 'admin', 'superadmin']

    def create_token(self, user_id: str, permission_indices: List[int]) -> str:
        """Create a signed access token with specified permission indices."""
        # Validate all indices are within the Permission enum range
        valid_perms = []
        for idx in permission_indices:
            if not isinstance(idx, int):
                raise ValueError(f"Permission index must be int, got {type(idx)}")
            if idx < 0:
                raise ValueError(f"Permission index cannot be negative: {idx}")
            # Allow indices 0-3 (READ through ADMIN)
            if idx > len(Permission):
                raise ValueError(f"Permission index {idx} exceeds maximum")
            valid_perms.append(idx)

        token = AccessToken(user_id=user_id, permissions=valid_perms, issued_at=__import__('time').time())

        # Sign the token
        token_data = json.dumps({
            'user_id': token.user_id,
            'permissions': token.permissions,
            'issued_at': token.issued_at,
            'nonce': token.nonce
        }).encode()

        signature = hmac.new(self._secret, token_data, hashlib.sha256).hexdigest()
        token_id = f"{token.nonce}:{signature[:16]}"
        self._registry[token_id] = token
        return token_id

    def check_permission(self, token_id: str, required_level: int) -> bool:
        """Check if a token has the required permission level."""
        if token_id not in self._registry:
            return False

        token = self._registry[token_id]

        # Check if any of the token's permission indices grant the required level
        for perm_idx in token.permissions:
            if perm_idx >= required_level:
                return True
        return False

    def get_permission_name(self, level_index: int) -> Optional[str]:
        """Get human-readable name for a permission level.

        Uses bounds checking to prevent out-of-range access.
        The _level_names array has 5 entries (indices 0-4).
        Valid permission levels are 0-3 (Permission enum).
        """
        # Bounds check: level_index must be non-negative and within array
        if level_index < 0:
            return None
        # Check against the length of the Permission enum (4 values: 0,1,2,3)
        # This ensures we only return names for valid permission levels
        if level_index >= len(Permission):
            return None
        return self._level_names[level_index]

    def get_effective_permissions(self, token_id: str) -> List[str]:
        """Return list of effective permission names for a token."""
        if token_id not in self._registry:
            return []

        token = self._registry[token_id]
        result = []
        for perm_idx in token.permissions:
            name = self.get_permission_name(perm_idx)
            if name:
                result.append(name)
        return result


class ResourceGateway:
    """Controls access to protected resources."""

    def __init__(self, registry: PermissionRegistry):
        self._registry = registry
        self._resources: Dict[str, Dict[str, Any]] = {}
        self._audit_log: List[Dict] = []

    def register_resource(self, name: str, min_permission: int, data: Any) -> None:
        """Register a resource with minimum permission requirement."""
        if min_permission < 0 or min_permission > Permission.ADMIN:
            raise ValueError(f"Invalid permission level: {min_permission}")
        self._resources[name] = {
            'min_permission': min_permission,
            'data': data
        }

    def access_resource(self, token_id: str, resource_name: str) -> Optional[Any]:
        """Attempt to access a resource with the given token."""
        if resource_name not in self._resources:
            self._audit_log.append({
                'action': 'access_denied',
                'reason': 'resource_not_found',
                'resource': resource_name,
                'token': token_id[:8] + '...'
            })
            return None

        resource = self._resources[resource_name]
        min_perm = resource['min_permission']

        if not self._registry.check_permission(token_id, min_perm):
            self._audit_log.append({
                'action': 'access_denied',
                'reason': 'insufficient_permission',
                'resource': resource_name,
                'required': min_perm,
                'token': token_id[:8] + '...'
            })
            return None

        self._audit_log.append({
            'action': 'access_granted',
            'resource': resource_name,
            'token': token_id[:8] + '...'
        })
        return resource['data']

    def get_audit_log(self) -> List[Dict]:
        """Return copy of audit log."""
        return list(self._audit_log)
